// ---------------------------------------------------------------- beginner words for the data courses
Object.assign(glossary, {
  row: { term: 'Row', def: 'One record in a table, read across: one account, one payment, one customer.' },
  column: { term: 'Column', def: 'One kind of information in a table, read downwards: every balance, every city. All values in a column are the same kind of thing.' },
  filter: { term: 'Filter', def: 'Keeping only the rows that pass a test, such as "days past due is over 60". The other rows are left out of the result, not deleted.' },
  array: { term: 'Array', def: 'NumPy\'s container for many values of the same type, stored side by side so maths can be done on all of them at once.' },
  mask: { term: 'Mask', def: 'A column or array of True and False values, one per row, made by a condition. It marks which rows to keep.' },
  join: { term: 'Join', def: 'Putting two tables side by side by matching rows that share a value, such as the same account id.' },
  datetime: { term: 'Datetime', def: 'A real date (and time) value that Python can compare, sort and subtract, as opposed to a date written as text.' },
  database: { term: 'Database', def: 'An organised store of data made of tables. You ask it questions in SQL instead of opening files.' },
  cte: { term: 'CTE (WITH)', def: 'A named step inside a query: WITH late AS (…) SELECT … FROM late. It lets a long query be read as a few short ones.' },
  axes: { term: 'Axes', def: 'In Matplotlib, one plotting area inside a figure: the box with its x and y scales where lines and bars are drawn.' },
  chart: { term: 'Chart', def: 'A picture of data: lines for change over time, bars for comparing categories, histograms for spread, scatter plots for relationships.' },
});
