// ---------------------------------------------------------------- beginner words for the React, Jira and Kubernetes courses
Object.assign(glossary, {
  reactkey: { term: 'Key (React)', def: 'A unique, unchanging id given to each item of a list (key={a.id}) so React can tell the items apart when the list changes.' },
  controlled: { term: 'Controlled input', def: 'A text box whose contents live in state: it shows value={text} and every keystroke calls setText. React, not the browser, holds the text.' },
  event: { term: 'Event', def: 'Something the user does, such as a click or a key press. You respond to it with a handler like onClick or onChange.' },
  project: { term: 'Project (Jira)', def: 'A container for one team\'s or one product\'s work. Each has a short key, such as COLL, that starts every work item\'s id.' },
  epic: { term: 'Epic', def: 'A large piece of work that takes several sprints, broken down into stories, tasks and bugs.' },
  status: { term: 'Status', def: 'Where a work item is right now: To Do, In Progress, In Review or Done.' },
  assignee: { term: 'Assignee and reporter', def: 'The assignee is the one person responsible for the work now. The reporter is whoever raised it.' },
  board: { term: 'Board', def: 'A view of work as cards in columns, one column per status. Moving a card changes its status.' },
  transition: { term: 'Transition', def: 'An allowed move from one status to another, such as In Progress → In Review. The workflow lists which moves exist.' },
  wip: { term: 'WIP limit', def: 'Work-in-progress limit: the most cards a column should hold at once. Going over it is a signal to finish work before starting more.' },
  backlog: { term: 'Backlog', def: 'The ordered list of everything the team might do, most important at the top. Sprints are filled from it.' },
  savedfilter: { term: 'Saved filter', def: 'A JQL search saved under a name so it can be reused, shared, or shown on a dashboard.' },
  dashboard: { term: 'Dashboard', def: 'A page of small panels (gadgets), each showing a chart or list built from a saved filter.' },
  burndown: { term: 'Burndown chart', def: 'A chart of the work left in a sprint, day by day. The line should fall to zero by the last day.' },
  cluster: { term: 'Cluster', def: 'A group of machines (nodes) managed together by Kubernetes, plus the control plane that decides what runs where.' },
  manifest: { term: 'Manifest (YAML)', def: 'A text file describing something you want Kubernetes to run: its kind, its name and its settings. You hand it over with kubectl apply.' },
  replica: { term: 'Replica', def: 'One of several identical copies of a pod. replicas: 3 means "keep three copies running".' },
  selector: { term: 'Selector', def: 'A label a Deployment or Service looks for, such as app: portfolio. Every pod carrying that label belongs to it.' },
  rollback: { term: 'Rollback', def: 'Going back to the previous version of an app after a bad update: kubectl rollout undo.' },
});
